export interface StageHost {
  stages: object[];
}

function isObject(value: unknown): value is object {
  return typeof value === "object" && value !== null;
}

export function attachStages(host: StageHost, additions: readonly object[]): void {
  if (!isObject(host) || !Array.isArray(host.stages) || !Array.isArray(additions)) {
    throw new TypeError("Invalid stage host or additions");
  }
  if (!host.stages.every(isObject) || !additions.every(isObject)) {
    throw new TypeError("Every stage must be a non-null object");
  }

  const seen = new Set<object>();
  for (const stage of additions) {
    if (!seen.has(stage)) {
      host.stages.push(stage);
      seen.add(stage);
    }
  }
}

