import { attachStages, type StageHost } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function same(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}
function throwsTypeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const first = {};
const duplicate = {};
const added = {};
const later = {};
const stages = [first, duplicate, duplicate];
const host: StageHost = { stages };
const additions = Object.freeze([duplicate, added, added, first, later]);
const result = attachStages(host, additions);
same(result, undefined, "attachStages must return undefined");
same(host.stages, stages, "the existing stages array must not be replaced");
same(stages.length, 5, "only new identities should be appended");
same(stages[0], first, "existing order changed");
same(stages[1], duplicate, "existing stage changed");
same(stages[2], duplicate, "existing duplicates must remain");
same(stages[3], added, "first accepted addition missing");
same(stages[4], later, "accepted addition order changed");
same(additions.length, 5, "additions must not be mutated");

const emptyStages: object[] = [];
attachStages({ stages: emptyStages }, []);
same(emptyStages.length, 0, "empty arrays should be accepted");

const stable = {};
const atomicStages: unknown[] = [stable];
throwsTypeError(
  () => attachStages({ stages: atomicStages as object[] }, [{}, null as unknown as object, {}]),
  "a malformed addition must throw TypeError",
);
same(atomicStages.length, 1, "addition validation must be atomic");
same(atomicStages[0], stable, "atomic failure changed existing content");

const malformedExisting: unknown[] = [{}, 1];
throwsTypeError(
  () => attachStages({ stages: malformedExisting as object[] }, [{}]),
  "a malformed existing stage must throw TypeError",
);
same(malformedExisting.length, 2, "malformed existing stages must not be mutated");

throwsTypeError(() => attachStages(null as unknown as StageHost, []), "null host must be rejected");
throwsTypeError(() => attachStages({ stages: null } as unknown as StageHost, []), "null stages must be rejected");
throwsTypeError(() => attachStages({ stages: {} } as unknown as StageHost, []), "non-array stages must be rejected");
throwsTypeError(() => attachStages({ stages: [] }, null as unknown as readonly object[]), "non-array additions must be rejected");

